client_script:
(function () {
	var WILAYAH_METHOD = "rumba16.api.get_rumba_wilayah_aktif";
	var UNIT_METHOD = "rumba16.api.get_rumba_units_by_kota";

	var wilayah = [];
	var mode_fallback = false;

	function field(fieldname) {
		return frappe.web_form.fields_dict[fieldname];
	}

	function set_autocomplete_options(fieldname, options) {
		var f = field(fieldname);
		if (f && typeof f.set_data === "function") {
			f.set_data(options);
		}
	}

	function refresh_select_field(fieldname, options) {
		var f = field(fieldname);
		if (!f) return;

		f.df.options = options.join("\n");

		if (f.$input) {
			f.$input.empty();
			options.forEach(function (option) {
				f.$input.append(
					$("<option></option>").attr("value", option).text(option)
				);
			});
		}

		f.refresh();
	}

	function jaga_opsi_autocomplete(fieldname, ambil_opsi) {
		var f = field(fieldname);
		if (!f) return;

		if (f.$input && !f.__rumba_jaga) {
			f.__rumba_jaga = true;
			f.$input.on("focus", function () {
				set_autocomplete_options(fieldname, ambil_opsi());
			});
		}

		[700, 1600, 3200].forEach(function (ms) {
			setTimeout(function () {
				set_autocomplete_options(fieldname, ambil_opsi());
			}, ms);
		});
	}

	function opsi_provinsi_saat_ini() {
		return wilayah.map(function (p) {
			return { value: p.kode_provinsi, label: p.nama_provinsi };
		});
	}

	function opsi_kota_saat_ini() {
		var provinsi = get_provinsi(frappe.web_form.get_value("kode_provinsi"));
		return provinsi
			? provinsi.kota.map(function (k) {
				return { value: k.kode_kota, label: k.nama_kota };
			})
			: [];
	}

	function get_provinsi(kode_provinsi) {
		for (var i = 0; i < wilayah.length; i++) {
			if (wilayah[i].kode_provinsi === kode_provinsi) return wilayah[i];
		}
		return null;
	}

	function get_kota(kode_provinsi, kode_kota) {
		var provinsi = get_provinsi(kode_provinsi);
		if (!provinsi) return null;
		for (var i = 0; i < provinsi.kota.length; i++) {
			if (provinsi.kota[i].kode_kota === kode_kota) return provinsi.kota[i];
		}
		return null;
	}

	function isi_opsi_provinsi() {
		set_autocomplete_options("kode_provinsi", wilayah.map(function (p) {
			return { value: p.kode_provinsi, label: p.nama_provinsi };
		}));
	}

	function isi_opsi_kota(kode_provinsi, pertahankan_nilai) {
		var provinsi = get_provinsi(kode_provinsi);
		var opsi = provinsi
			? provinsi.kota.map(function (k) {
				return { value: k.kode_kota, label: k.nama_kota };
			})
			: [];

		set_autocomplete_options("nama_kota", opsi);

		var nilai_kota = pertahankan_nilai
			? frappe.web_form.get_value("nama_kota")
			: "";

		if (!pertahankan_nilai) {
			frappe.web_form.set_value("nama_kota", "");
			frappe.web_form.set_value("nama_unit", "");
			refresh_select_field("nama_unit", [""]);
		}

		if (opsi.length === 1 && !nilai_kota) {
			frappe.web_form.set_value("nama_kota", opsi[0].value);
		}
	}

	function isi_opsi_unit(kode_provinsi, kode_kota, pertahankan_nilai) {
		var kota = get_kota(kode_provinsi, kode_kota);
		var units = kota ? kota.unit : [];
		var opsi = [""].concat(units.map(function (u) {
			return u.name || u.nama_unit;
		}));

		refresh_select_field("nama_unit", opsi);

		var nilai_unit = pertahankan_nilai
			? frappe.web_form.get_value("nama_unit")
			: "";

		if (!pertahankan_nilai) {
			frappe.web_form.set_value("nama_unit", "");
		}

		if (units.length === 1 && !nilai_unit) {
			frappe.web_form.set_value(
				"nama_unit",
				units[0].name || units[0].nama_unit
			);
		}
	}

	function aktifkan_fallback() {
		mode_fallback = true;
		frappe.web_form.set_df_property("kode_provinsi", "reqd", 0);
		frappe.web_form.set_df_property("kode_provinsi", "hidden", 1);
		muat_unit_fallback(frappe.web_form.get_value("nama_kota"));
	}

	function muat_unit_fallback(kode_kota) {
		if (!kode_kota) {
			refresh_select_field("nama_unit", [""]);
			return;
		}
		frappe.call({
			method: UNIT_METHOD,
			args: { kode_kota: kode_kota },
			callback: function (r) {
				var units = r.message || [];
				refresh_select_field("nama_unit", [""].concat(
					units.map(function (u) { return u.name || u.nama_unit; })
				));
			},
			error: function () {
				refresh_select_field("nama_unit", [""]);
			}
		});
	}

	function muat_wilayah() {
		frappe.call({
			method: WILAYAH_METHOD,
			callback: function (r) {
				wilayah = r.message || [];
				isi_opsi_provinsi();
				jaga_opsi_autocomplete("kode_provinsi", opsi_provinsi_saat_ini);
				jaga_opsi_autocomplete("nama_kota", opsi_kota_saat_ini);

				var provinsi = frappe.web_form.get_value("kode_provinsi");
				var kota = frappe.web_form.get_value("nama_kota");

				if (provinsi) isi_opsi_kota(provinsi, true);
				if (provinsi && kota) isi_opsi_unit(provinsi, kota, true);

				if (wilayah.length === 1 && !provinsi) {
					frappe.web_form.set_value(
						"kode_provinsi", wilayah[0].kode_provinsi
					);
				}
			},
			error: function () {
				aktifkan_fallback();
			}
		});
	}

	frappe.web_form.after_load = function () {
		muat_wilayah();
	};

	frappe.web_form.on("kode_provinsi", function (f, value) {
		if (mode_fallback) return;
		isi_opsi_kota(value, false);
	});

	frappe.web_form.on("nama_kota", function (f, value) {
		if (mode_fallback) {
			muat_unit_fallback(value);
			return;
		}
		isi_opsi_unit(frappe.web_form.get_value("kode_provinsi"), value, false);
	});
})();
